package top.dcpstudios.calendarwidget;
import android.app.*;import android.graphics.Typeface;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

final class MessageScreen {
 final MainActivity a;LinearLayout list;TextView summary;String query="";int tab=0;Set<String> expanded=new HashSet<>(),summarizing=new HashSet<>();Map<String,Integer> limits=new HashMap<>();Map<String,String> summaries=new HashMap<>();
 MessageScreen(MainActivity activity){a=activity;}
 String rendered="";LinearLayout renderedList;
 void show(){a.base("messages");LinearLayout top=new LinearLayout(a);top.setGravity(Gravity.CENTER_VERTICAL);TextView title=a.text("消息终端",26,a.ink);title.setTypeface(null,Typeface.BOLD);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button read=a.button("一键已读",()->TerminalClient.markAllRead(a,this::render));top.addView(read,new LinearLayout.LayoutParams(a.d(88),a.d(40)));a.root.addView(top);a.space(a.root,8);
  EditText search=new EditText(a);search.setSingleLine();search.setTextSize(13);search.setTextColor(a.ink);search.setHintTextColor(a.muted);search.setHint("搜索会话或消息");search.setPadding(a.d(12),0,a.d(12),0);search.setBackground(a.bg(a.surface,8));search.setText(query);a.root.addView(search,new LinearLayout.LayoutParams(-1,a.d(40)));
  Ui.Choice tabs=new Ui.Choice(a,new String[]{"全部","群聊","联系人","其它"},tab,4);tabs.onChange(n->{tab=n;render();});a.root.addView(tabs);summary=a.text("",11,a.muted);summary.setPadding(0,a.d(4),0,a.d(8));a.root.addView(summary);list=a.column();ScrollView scroll=new ScrollView(a);scroll.addView(list);a.root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));a.navigation("messages");
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){query=s.toString();render();}public void afterTextChanged(Editable e){}});render();TerminalClient.refresh(a,this::render);
 }
 String key(JSONObject m){JSONObject p=m.optJSONObject("payload");String chat=p==null?"":p.optString("chat_id");return m.optString("source")+":"+(chat.isEmpty()?m.optString("chat",m.optString("title")):chat);}
 String sender(JSONObject m){JSONObject p=m.optJSONObject("payload");return p==null?"":p.optString("sender_name",p.optString("sender_id",""));}
 void render(){if(!"messages".equals(a.page)||list==null)return;List<JSONObject> messages=TerminalDb.get(a).messages(query);String signature=query+tab+messages.toString()+summarizing.toString()+TerminalClient.prefs(a).getString("error","")+TerminalDb.get(a).unread();if(renderedList==list&&signature.equals(rendered))return;renderedList=list;rendered=signature;list.removeAllViews();LinkedHashMap<String,List<JSONObject>> chats=new LinkedHashMap<>();for(JSONObject m:messages){boolean wx=m.optString("source").equals("wechat"),group=key(m).endsWith("@chatroom");if(tab==1&&(!wx||!group)||tab==2&&(!wx||group)||tab==3&&wx)continue;String key=key(m);if(!chats.containsKey(key))chats.put(key,new ArrayList<>());chats.get(key).add(m);}
  String error=TerminalClient.prefs(a).getString("error","");summary.setText(TerminalDb.get(a).unread()+" 条未读 · "+chats.size()+" 个会话"+(error.isEmpty()?"":"\n"+error));
  for(Map.Entry<String,List<JSONObject>> entry:chats.entrySet()){String key=entry.getKey();List<JSONObject> rows=entry.getValue();JSONObject latest=rows.get(0);List<JSONObject> unreadRows=new ArrayList<>();for(JSONObject r:rows)if(!r.optBoolean("is_read"))unreadRows.add(r);int unread=unreadRows.size();LinearLayout card=a.column();card.setPadding(a.d(10),a.d(8),a.d(10),a.d(8));VisualStyles.apply(a,card,VisualStyles.message(latest));LinearLayout header=new LinearLayout(a);header.setGravity(Gravity.CENTER_VERTICAL);LinearLayout label=a.column();TextView name=a.text((expanded.contains(key)?"⌄  ":"›  ")+latest.optString("title"),14,a.ink);name.setTypeface(null,Typeface.BOLD);label.addView(name);label.addView(a.text(rows.size()+" 条 · "+unread+" 未读 · "+new java.text.SimpleDateFormat("M/d HH:mm",Locale.CHINA).format(new Date(latest.optLong("occurred_at"))),10,a.muted));header.addView(label,new LinearLayout.LayoutParams(0,-2,1));
   LinearLayout content=a.column();Runnable toggle=()->{if(!expanded.remove(key))expanded.add(key);name.setText((expanded.contains(key)?"⌄  ":"›  ")+latest.optString("title"));Ui.resizeContent(content,()->fillContent(content,key,rows,name));};label.setOnClickListener(v->toggle.run());Ui.press(label);
   if(unread>100&&latest.optString("source").equals("wechat")){Button sum=a.button(summarizing.contains(key)?"总结中":"总结",()->summarize(key,unreadRows));sum.setEnabled(!summarizing.contains(key));header.addView(sum,new LinearLayout.LayoutParams(a.d(62),a.d(38)));}card.addView(header);card.addView(content);fillContent(content,key,rows,name);
   LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=a.d(8);list.addView(card,lp);
  }if(chats.isEmpty())list.addView(a.text("没有匹配的消息",13,a.muted));
 }
 void fillContent(LinearLayout content,String key,List<JSONObject> rows,TextView name){content.removeAllViews();JSONObject latest=rows.get(0);if(expanded.contains(key)){int limit=limits.containsKey(key)?limits.get(key):30;for(int i=0;i<Math.min(limit,rows.size());i++)addMessage(content,rows.get(i));if(rows.size()>limit)content.addView(a.button("更多消息",()->{limits.put(key,limit+30);Ui.resizeContent(content,()->fillContent(content,key,rows,name));}));}else{TextView preview=a.text((sender(latest).isEmpty()?"":sender(latest)+"：")+latest.optString("body"),12,a.muted);preview.setPadding(0,a.d(6),0,0);preview.setMaxLines(2);preview.setEllipsize(TextUtils.TruncateAt.END);preview.setOnClickListener(v->{expanded.add(key);name.setText("⌄  "+latest.optString("title"));Ui.resizeContent(content,()->fillContent(content,key,rows,name));});content.addView(preview);}}
 void addMessage(LinearLayout parent,JSONObject m){LinearLayout row=a.column();row.setPadding(a.d(4),a.d(7),a.d(4),a.d(6));row.addView(a.text((m.optBoolean("is_read")?"":"● ")+sender(m)+" · "+new java.text.SimpleDateFormat("M/d HH:mm",Locale.CHINA).format(new Date(m.optLong("occurred_at"))),10,a.muted));TextView body=a.text(m.optString("body"),13,a.ink);body.setMaxLines(5);body.setEllipsize(TextUtils.TruncateAt.END);row.addView(body);row.setOnClickListener(v->detail(m));parent.addView(row);View line=new View(a);line.setBackgroundColor(a.line);parent.addView(line,new LinearLayout.LayoutParams(-1,a.d(1)));}
 void summarize(String key,List<JSONObject> rows){String cacheKey=key+":"+rows.get(0).optLong("id")+":"+rows.size();if(summaries.containsKey(cacheKey)){showSummary(summaries.get(cacheKey));return;}new AlertDialog.Builder(a).setTitle("总结此会话").setMessage("将这 "+rows.size()+" 条消息发送到已配置的 LLM 接口，会产生模型用量。").setNegativeButton("取消",null).setPositiveButton("总结",(d,w)->{summarizing.add(key);render();TerminalClient.IO.execute(()->{try{JSONArray ids=new JSONArray();for(JSONObject r:rows)ids.put(r.optLong("id"));NetDiskSession.Reply result=TerminalClient.requestBound(a,"/conversations/summary",new JSONObject().put("message_ids",ids),null);String text=result.data.getString("summary");NetDiskSession.ui(a,result.account,()->{summaries.put(cacheKey,text);if(!a.isDestroyed())showSummary(text);});}catch(NetDiskSession.AccountChanged ignored){}catch(Exception e){a.runOnUiThread(()->a.error(e));}finally{a.runOnUiThread(()->{summarizing.remove(key);render();});}});}).show();}
 void showSummary(String text){TextView content=a.text(text,14,a.ink);content.setTextIsSelectable(true);content.setPadding(a.d(18),a.d(12),a.d(18),a.d(12));ScrollView scroll=new ScrollView(a);scroll.addView(content);new AlertDialog.Builder(a).setTitle("会话总结").setView(scroll).setPositiveButton("关闭",null).show();}
 void detail(JSONObject m){if(!m.optBoolean("is_read"))TerminalClient.markRead(a,m.optLong("id"),true);new ConversationScreen(a,m).show();}
}
